import React, { useState, useMemo } from &#39;react&#39;;
import { 
  Settings, GitFork, ListOrdered, Shapes, 
  RefreshCcw, Users, Calculator, Sparkles, BookOpen, Fingerprint, Layers, Globe
} from &#39;lucide-react&#39;;

// --- Token Sets for Universal Use ---
const TOKEN_SETS = {
  numbers: [&#39;1&#39;, &#39;2&#39;, &#39;3&#39;, &#39;4&#39;, &#39;5&#39;, &#39;6&#39;],
  letters: [&#39;A&#39;, &#39;B&#39;, &#39;C&#39;, &#39;D&#39;, &#39;E&#39;, &#39;F&#39;],
  colors:  [&#39;🔴&#39;, &#39;🔵&#39;, &#39;🟢&#39;, &#39;🟡&#39;, &#39;🟣&#39;, &#39;🟠&#39;],
  shapes:  [&#39;▲&#39;, &#39;■&#39;, &#39;●&#39;, &#39;★&#39;, &#39;◆&#39;, &#39;⬟&#39;]
};

// --- The 4 Universal Quadrants ---
const QUADRANTS = {
  P_REP: { // Permutation with Repetition
    id: &#39;P_REP&#39;,
    name: &quot;Unrestricted Sequence&quot;,
    formula: &quot;n^r&quot;,
    orderMatters: true,
    reuseAllowed: true,
    theme: { bg: &#39;bg-purple-50&#39;, border: &#39;border-purple-200&#39;, text: &#39;text-purple-700&#39;, fill: &#39;fill-purple-500&#39;, stroke: &#39;stroke-purple-500&#39; },
    perspective: {
      title: &quot;The West African Weaver&quot;,
      role: &quot;Kente Cloth Artisan&quot;,
      text: &quot;When weaving a pattern, I can use the same color thread over and over (Reuse Allowed). The specific sequence of those threads—Red, Gold, Red vs. Gold, Red, Gold—creates an entirely different meaning (Order Matters). The possibilities are an endless, unrestricted tree.&quot;
    }
  },
  P_NOREP: { // Permutation without Repetition
    id: &#39;P_NOREP&#39;,
    name: &quot;Strict Arrangement&quot;,
    formula: &quot;n! / (n-r)!&quot;,
    orderMatters: true,
    reuseAllowed: false,
    theme: { bg: &#39;bg-blue-50&#39;, border: &#39;border-blue-200&#39;, text: &#39;text-blue-700&#39;, fill: &#39;fill-blue-500&#39;, stroke: &#39;stroke-blue-500&#39; },
    perspective: {
      title: &quot;The Japanese Calligrapher&quot;,
      role: &quot;Shodō Master&quot;,
      text: &quot;A brush stroke is an event in time. Once a specific stroke is made, it cannot be made again in that exact way (No Reuse). The sequence in which the strokes are laid down determines if the character is correct or gibberish (Order Matters). History does not repeat.&quot;
    }
  },
  C_REP: { // Combination with Repetition
    id: &#39;C_REP&#39;,
    name: &quot;Multiset Mixture&quot;,
    formula: &quot;(n+r-1)! / [r!(n-1)!]&quot;,
    orderMatters: false,
    reuseAllowed: true,
    theme: { bg: &#39;bg-amber-50&#39;, border: &#39;border-amber-200&#39;, text: &#39;text-amber-700&#39;, fill: &#39;fill-amber-500&#39;, stroke: &#39;stroke-amber-500&#39; },
    perspective: {
      title: &quot;The Indian Spice Merchant&quot;,
      role: &quot;Masala Blender&quot;,
      text: &quot;I am building a spice blend. I can add three scoops of cumin if I want (Reuse Allowed). But once the spices are tossed together in the bowl, it does not matter which scoop hit the bottom first (Order Neutral). The tree forces us to only look at the final mixture.&quot;
    }
  },
  C_NOREP: { // Combination without Repetition
    id: &#39;C_NOREP&#39;,
    name: &quot;Pure Subset&quot;,
    formula: &quot;n! / [r!(n-r)!]&quot;,
    orderMatters: false,
    reuseAllowed: false,
    theme: { bg: &#39;bg-emerald-50&#39;, border: &#39;border-emerald-200&#39;, text: &#39;text-emerald-700&#39;, fill: &#39;fill-emerald-500&#39;, stroke: &#39;stroke-emerald-500&#39; },
    perspective: {
      title: &quot;The Appalachian Forager&quot;,
      role: &quot;Wildcrafter&quot;,
      text: &quot;I am gathering unique wild herbs for a tincture. I only take one of each distinct plant (No Reuse). When I drop them into my basket, they are simply &#39;together&#39;. There is no first or last, only the collection (Order Neutral). The ultimate reduction of choices.&quot;
    }
  }
};

// --- Recursive SVG Tree Component ---
const TreeBranch = ({ 
  node, x, y, spacing, depth, maxDepth, 
  activeHoverPath, currentPath = [], currentIndices = [],
  quadrant
}) =&gt; {
  if (!node || !node.children || node.children.length === 0 || depth &gt;= maxDepth) return null;
  const totalWidth = (node.children.length - 1) * spacing;

  return (
    &lt;g&gt;
      {node.children.map((child, i) =&gt; {
        const childX = x - totalWidth / 2 + i * spacing;
        const childY = y + 55;

        const thisPath = [...currentPath, child.name];
        const thisIndices = [...currentIndices, child.index];

        // --- Universal Pruning Engine ---
        const isUnique = new Set(thisIndices).size === thisIndices.length;
        let isSorted = true;
        for (let j = 1; j &lt; thisIndices.length; j++) {
          if (!quadrant.reuseAllowed &amp;&amp; thisIndices[j] &lt;= thisIndices[j-1]) isSorted = false;
          if (quadrant.reuseAllowed &amp;&amp; thisIndices[j] &lt; thisIndices[j-1]) isSorted = false;
        }

        let isValid = true;
        if (!quadrant.reuseAllowed &amp;&amp; !isUnique) isValid = false;
        if (!quadrant.orderMatters &amp;&amp; !isSorted) isValid = false;

        const isPathHovered = activeHoverPath &amp;&amp; activeHoverPath[depth] === child.name &amp;&amp; activeHoverPath.join(&#39;&#39;) === thisPath.slice(0, activeHoverPath.length).join(&#39;&#39;);

        let strokeColor, strokeWidth, circleFill, textColor;

        if (activeHoverPath) {
          if (isPathHovered) {
            strokeColor = quadrant.theme.stroke;
            strokeWidth = &#39;stroke-[3px]&#39;;
            circleFill = quadrant.theme.fill;
            textColor = &#39;fill-white&#39;;
          } else {
            strokeColor = &#39;stroke-slate-200 opacity-20&#39;;
            strokeWidth = &#39;stroke-[1px]&#39;;
            circleFill = &#39;fill-white opacity-20&#39;;
            textColor = &#39;fill-slate-400 opacity-20&#39;;
          }
        } else {
          if (isValid) {
            strokeColor = quadrant.theme.stroke;
            strokeWidth = &#39;stroke-[2px]&#39;;
            circleFill = &#39;fill-white&#39;;
            textColor = &#39;fill-slate-800&#39;;
          } else {
            strokeColor = &#39;stroke-slate-200 opacity-40&#39;;
            strokeWidth = &#39;stroke-[1.5px] stroke-dasharray-[2,2]&#39;;
            circleFill = &#39;fill-slate-50 opacity-50&#39;;
            textColor = &#39;fill-slate-300 opacity-50&#39;;
          }
        }

        return (
          &lt;React.Fragment key={`branch-${depth}-${i}-${child.name}`}&gt;
            &lt;line 
              x1={x} y1={y + 12} x2={childX} y2={childY - 12} 
              className={`${strokeWidth} ${strokeColor} transition-all duration-300`}
            /&gt;
            &lt;g transform={`translate(${childX}, ${childY})`}&gt;
              &lt;circle r=&quot;14&quot; className={`${circleFill} ${strokeWidth} ${strokeColor} transition-all duration-300`} /&gt;
              &lt;text 
                textAnchor=&quot;middle&quot; dy=&quot;4&quot; 
                className={`text-[10px] font-bold pointer-events-none select-none ${textColor} transition-all duration-300`}
              &gt;
                {child.name}
              &lt;/text&gt;
              &lt;TreeBranch 
                node={child} x={0} y={0} spacing={spacing * 0.45} depth={depth + 1} 
                maxDepth={maxDepth} activeHoverPath={isPathHovered ? activeHoverPath : null}
                currentPath={thisPath} currentIndices={thisIndices} quadrant={quadrant}
              /&gt;
            &lt;/g&gt;
          &lt;/React.Fragment&gt;
        );
      })}
    &lt;/g&gt;
  );
};

const App = () =&gt; {
  const [tokenType, setTokenType] = useState(&#39;numbers&#39;);
  const [n, setN] = useState(3);
  const [r, setR] = useState(2);
  const [activeQuadId, setActiveQuadId] = useState(&#39;P_NOREP&#39;);
  const [activePath, setActivePath] = useState(null);

  const quadrant = QUADRANTS[activeQuadId];
  const items = useMemo(() =&gt; TOKEN_SETS[tokenType].slice(0, n), [tokenType, n]);

  const fact = (num) =&gt; (num &lt;= 1 ? 1 : num * fact(num - 1));

  // The Universal Math Engine
  const mathDetails = useMemo(() =&gt; {
    if (quadrant.id === &#39;P_REP&#39;) return { count: Math.pow(n, r) };
    if (quadrant.id === &#39;P_NOREP&#39;) return { count: fact(n) / fact(n - r) };
    if (quadrant.id === &#39;C_REP&#39;) return { count: fact(n + r - 1) / (fact(r) * fact(n - 1)) };
    if (quadrant.id === &#39;C_NOREP&#39;) return { count: fact(n) / (fact(r) * fact(n - r)) };
  }, [n, r, quadrant]);

  // The Master Tree Generator (Always generates n^r unrestricted paths)
  const masterTreeData = useMemo(() =&gt; {
    const root = { name: &quot;Root&quot;, children: [], index: -1 };
    const build = (node, depth) =&gt; {
      if (depth === r) return;
      items.forEach((item, idx) =&gt; {
        const child = { name: item, index: idx, children: [] };
        node.children.push(child);
        // Visual safety cap to prevent SVG explosion
        if (depth &lt; (n &gt; 4 ? 1 : 2)) build(child, depth + 1); 
      });
    };
    build(root, 0);
    return root;
  }, [items, r, n]);

  // Valid Paths Generator
  const validPaths = useMemo(() =&gt; {
    let res = [];
    const bt = (currPath, currIndices) =&gt; {
      if (currPath.length === r) {
        const isUnique = new Set(currIndices).size === currIndices.length;
        let isSorted = true;
        for (let j = 1; j &lt; currIndices.length; j++) {
          if (!quadrant.reuseAllowed &amp;&amp; currIndices[j] &lt;= currIndices[j-1]) isSorted = false;
          if (quadrant.reuseAllowed &amp;&amp; currIndices[j] &lt; currIndices[j-1]) isSorted = false;
        }

        let isValid = true;
        if (!quadrant.reuseAllowed &amp;&amp; !isUnique) isValid = false;
        if (!quadrant.orderMatters &amp;&amp; !isSorted) isValid = false;

        if (isValid) res.push([...currPath]);
        return;
      }

      items.forEach((item, idx) =&gt; {
        currPath.push(item);
        currIndices.push(idx);
        bt(currPath, currIndices);
        currPath.pop();
        currIndices.pop();
      });
    };
    bt([], []);
    return res;
  }, [items, r, quadrant]);

  return (
    &lt;div className=&quot;min-h-screen bg-slate-100 p-4 md:p-8 font-sans text-slate-900&quot;&gt;

      &lt;header className=&quot;max-w-7xl mx-auto mb-6 text-center&quot;&gt;
        &lt;h1 className=&quot;text-3xl md:text-4xl font-black text-slate-800 tracking-tight flex items-center justify-center gap-3&quot;&gt;
          &lt;Calculator className=&quot;text-indigo-600&quot; size={32} /&gt;
          Universal Combinatorics Visualizer
        &lt;/h1&gt;
        &lt;p className=&quot;text-slate-500 mt-2 max-w-2xl mx-auto&quot;&gt;
          Plug in any scenario. Set your variables, choose your rules in the matrix, and watch the math physically carve the probability space.
        &lt;/p&gt;
      &lt;/header&gt;

      &lt;main className=&quot;max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-6&quot;&gt;

        {/* Left Panel: The Input Engine */}
        &lt;section className=&quot;lg:col-span-4 flex flex-col gap-6&quot;&gt;

          {/* Variables */}
          &lt;div className=&quot;bg-white p-6 rounded-3xl shadow-sm border border-slate-200&quot;&gt;
            &lt;h3 className=&quot;text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2&quot;&gt;
              &lt;Layers size={14} /&gt; 1. Set Variables
            &lt;/h3&gt;

            &lt;div className=&quot;space-y-5&quot;&gt;
              &lt;div&gt;
                &lt;label className=&quot;text-xs font-bold text-slate-600 mb-2 block&quot;&gt;Token Type&lt;/label&gt;
                &lt;div className=&quot;flex bg-slate-100 p-1 rounded-xl&quot;&gt;
                  {Object.keys(TOKEN_SETS).map(type =&gt; (
                    &lt;button 
                      key={type} onClick={() =&gt; setTokenType(type)}
                      className={`flex-1 py-1.5 text-xs font-bold rounded-lg capitalize transition-all ${tokenType === type ? &#39;bg-white shadow-sm text-indigo-600&#39; : &#39;text-slate-500 hover:text-slate-700&#39;}`}
                    &gt;
                      {type}
                    &lt;/button&gt;
                  ))}
                &lt;/div&gt;
                &lt;div className=&quot;mt-3 flex gap-1 justify-center&quot;&gt;
                  {items.map((it, idx) =&gt; &lt;span key={idx} className=&quot;w-8 h-8 flex items-center justify-center bg-slate-50 border border-slate-200 rounded-lg text-sm&quot;&gt;{it}&lt;/span&gt;)}
                &lt;/div&gt;
              &lt;/div&gt;

              &lt;div&gt;
                &lt;label className=&quot;flex justify-between text-xs font-bold text-slate-600 mb-2&quot;&gt;
                  &lt;span&gt;Total Pool ($n$)&lt;/span&gt;
                  &lt;span className=&quot;text-indigo-600&quot;&gt;{n}&lt;/span&gt;
                &lt;/label&gt;
                &lt;input 
                  type=&quot;range&quot; min=&quot;2&quot; max=&quot;6&quot; value={n} 
                  onChange={(e) =&gt; {
                    const val = parseInt(e.target.value);
                    setN(val);
                    if (r &gt; val &amp;&amp; !quadrant.reuseAllowed) setR(val);
                  }}
                  className=&quot;w-full h-1.5 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600&quot;
                /&gt;
              &lt;/div&gt;

              &lt;div&gt;
                &lt;label className=&quot;flex justify-between text-xs font-bold text-slate-600 mb-2&quot;&gt;
                  &lt;span&gt;Selections ($r$)&lt;/span&gt;
                  &lt;span className=&quot;text-indigo-600&quot;&gt;{r}&lt;/span&gt;
                &lt;/label&gt;
                &lt;input 
                  type=&quot;range&quot; min=&quot;1&quot; max={quadrant.reuseAllowed ? 4 : n} value={r} 
                  onChange={(e) =&gt; setR(parseInt(e.target.value))}
                  className=&quot;w-full h-1.5 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600&quot;
                /&gt;
              &lt;/div&gt;
            &lt;/div&gt;
          &lt;/div&gt;

          {/* The Matrix */}
          &lt;div className=&quot;bg-white p-6 rounded-3xl shadow-sm border border-slate-200&quot;&gt;
             &lt;h3 className=&quot;text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2&quot;&gt;
              &lt;Fingerprint size={14} /&gt; 2. The Combinatorics Matrix
            &lt;/h3&gt;

            &lt;div className=&quot;grid grid-cols-2 gap-2 relative&quot;&gt;
              {/* Matrix Labels */}
              &lt;div className=&quot;absolute -left-6 top-1/2 -translate-y-1/2 -rotate-90 text-[9px] font-bold uppercase text-slate-400 tracking-widest&quot;&gt;Order Matters?&lt;/div&gt;
              &lt;div className=&quot;absolute -top-6 left-1/2 -translate-x-1/2 text-[9px] font-bold uppercase text-slate-400 tracking-widest&quot;&gt;Reuse Allowed?&lt;/div&gt;

              {/* Quadrants */}
              {[QUADRANTS.P_REP, QUADRANTS.C_REP, QUADRANTS.P_NOREP, QUADRANTS.C_NOREP].map((quad) =&gt; (
                &lt;button
                  key={quad.id}
                  onClick={() =&gt; {
                    setActiveQuadId(quad.id);
                    // Adjust R if switching to a mode that doesn&#39;t allow r &gt; n
                    if (!quad.reuseAllowed &amp;&amp; r &gt; n) setR(n);
                  }}
                  className={`p-3 rounded-2xl border text-left flex flex-col transition-all duration-300 ${activeQuadId === quad.id ? `${quad.theme.bg} ${quad.theme.border} ring-2 ring-${quad.theme.stroke.split(&#39;-&#39;)[1]}-400 shadow-md` : &#39;bg-slate-50 border-slate-100 hover:bg-slate-100&#39;}`}
                &gt;
                  &lt;div className={`text-[10px] font-black uppercase mb-1 ${activeQuadId === quad.id ? quad.theme.text : &#39;text-slate-400&#39;}`}&gt;
                    {quad.orderMatters ? &#39;Permutation&#39; : &#39;Combination&#39;}
                  &lt;/div&gt;
                  &lt;div className={`text-xs font-medium leading-tight ${activeQuadId === quad.id ? &#39;text-slate-800&#39; : &#39;text-slate-500&#39;}`}&gt;
                    {quad.reuseAllowed ? &#39;With Repetition&#39; : &#39;No Repetition&#39;}
                  &lt;/div&gt;
                &lt;/button&gt;
              ))}
            &lt;/div&gt;
          &lt;/div&gt;

          {/* The Math output */}
          &lt;div className=&quot;bg-slate-900 p-6 rounded-3xl shadow-xl relative overflow-hidden text-white&quot;&gt;
            &lt;h3 className=&quot;text-[10px] font-bold uppercase tracking-widest mb-3 text-slate-400&quot;&gt;3. Formula Translation&lt;/h3&gt;
            &lt;div className=&quot;flex items-end gap-3 mb-3&quot;&gt;
              &lt;div className=&quot;text-5xl font-mono font-black&quot;&gt;{mathDetails.count}&lt;/div&gt;
              &lt;div className=&quot;text-sm font-mono mb-1 text-slate-400&quot;&gt;Paths&lt;/div&gt;
            &lt;/div&gt;
            &lt;div className=&quot;bg-white/10 p-3 rounded-xl border border-white/10 inline-block&quot;&gt;
              &lt;div className=&quot;text-lg font-mono text-emerald-400&quot;&gt;{quadrant.formula}&lt;/div&gt;
            &lt;/div&gt;
          &lt;/div&gt;

        &lt;/section&gt;

        {/* Right Panel: The Visualizer &amp; Philosophy */}
        &lt;section className=&quot;lg:col-span-8 flex flex-col gap-6&quot;&gt;

          &lt;div className=&quot;bg-white p-6 rounded-3xl shadow-sm border border-slate-200 flex flex-col md:flex-row gap-6 h-[500px]&quot;&gt;

             {/* The SVG Tree Graph */}
             &lt;div className=&quot;flex-1 flex flex-col relative h-full&quot;&gt;
                &lt;div className=&quot;flex items-center justify-between mb-3 relative z-10&quot;&gt;
                  &lt;div&gt;
                    &lt;div className=&quot;flex items-center gap-2 font-bold uppercase tracking-widest text-xs text-slate-800&quot;&gt;
                      &lt;GitFork size={16} /&gt; The Master Tree
                    &lt;/div&gt;
                    &lt;div className={`text-[10px] font-bold mt-1 uppercase ${quadrant.theme.text}`}&gt;{quadrant.name}&lt;/div&gt;
                  &lt;/div&gt;
                &lt;/div&gt;

                &lt;div className=&quot;flex-1 bg-slate-50/50 rounded-2xl border border-slate-100 overflow-hidden relative z-10&quot;&gt;
                  &lt;svg width=&quot;100%&quot; height=&quot;100%&quot; viewBox=&quot;0 0 600 400&quot; preserveAspectRatio=&quot;xMidYMin meet&quot;&gt;
                    &lt;g transform=&quot;translate(300, 30)&quot;&gt;
                      &lt;circle r=&quot;16&quot; className=&quot;fill-slate-800&quot; /&gt;
                      &lt;text textAnchor=&quot;middle&quot; dy=&quot;4&quot; className=&quot;fill-white text-[9px] font-bold&quot;&gt;START&lt;/text&gt;
                      &lt;TreeBranch 
                        node={masterTreeData} 
                        x={0} y={0} 
                        spacing={n &gt; 4 ? n * 25 : n * 45} 
                        depth={0} 
                        quadrant={quadrant}
                        maxDepth={n &gt; 4 &amp;&amp; r &gt;= 3 ? 2 : r} // Visual cap for huge trees
                        activeHoverPath={activePath}
                      /&gt;
                    &lt;/g&gt;
                  &lt;/svg&gt;
                  {n &gt; 4 &amp;&amp; r &gt;= 3 &amp;&amp; (
                    &lt;div className=&quot;absolute bottom-4 left-0 w-full flex justify-center&quot;&gt;
                      &lt;div className=&quot;bg-white/90 backdrop-blur px-3 py-1.5 rounded-full border border-slate-200 text-[9px] font-bold text-slate-500 shadow-sm&quot;&gt;
                        Tree graphic truncated to depth 2 to prevent visual clutter. List displays all {mathDetails.count} paths.
                      &lt;/div&gt;
                    &lt;/div&gt;
                  )}
                &lt;/div&gt;
             &lt;/div&gt;

             {/* Valid Outcomes List */}
             &lt;div className=&quot;w-full md:w-64 flex flex-col h-full&quot;&gt;
                &lt;div className=&quot;flex-1 bg-slate-50 rounded-2xl border border-slate-100 p-4 flex flex-col overflow-hidden h-full&quot;&gt;
                  &lt;div className=&quot;flex flex-col gap-1 mb-3&quot;&gt;
                    &lt;h3 className=&quot;text-[10px] font-bold text-slate-500 uppercase tracking-widest&quot;&gt;
                      Valid Outcomes
                    &lt;/h3&gt;
                    &lt;span className=&quot;text-[9px] text-slate-400 italic&quot;&gt;Hover to trace the sequence.&lt;/span&gt;
                  &lt;/div&gt;
                  &lt;div className=&quot;flex-1 overflow-y-auto pr-1 custom-scrollbar flex flex-col gap-1.5&quot;&gt;
                    {validPaths.map((path, idx) =&gt; (
                      &lt;div 
                        key={idx} 
                        onMouseEnter={() =&gt; setActivePath(path)}
                        onMouseLeave={() =&gt; setActivePath(null)}
                        className={`border px-3 py-2 rounded-xl flex items-center gap-2 transition-all cursor-default ${activePath === path ? `border-${quadrant.theme.stroke.split(&#39;-&#39;)[1]}-400 bg-white shadow-md scale-[1.02] z-10` : &#39;bg-white border-slate-100 hover:border-slate-300&#39;}`}
                      &gt;
                        &lt;span className=&quot;text-[10px] text-slate-300 font-mono w-4 text-right&quot;&gt;{idx + 1}.&lt;/span&gt;
                        &lt;div className=&quot;flex gap-1 font-mono font-bold text-slate-700&quot;&gt;
                          {path.map((item, i) =&gt; &lt;span key={i}&gt;{item}&lt;/span&gt;)}
                        &lt;/div&gt;
                      &lt;/div&gt;
                    ))}
                  &lt;/div&gt;
                &lt;/div&gt;
             &lt;/div&gt;
          &lt;/div&gt;

          {/* Universal Intuition Panel */}
          &lt;div className={`p-6 rounded-3xl border transition-all duration-500 ${quadrant.theme.bg} ${quadrant.theme.border}`}&gt;
            &lt;h4 className={`text-xs font-bold uppercase tracking-widest mb-3 flex items-center gap-2 ${quadrant.theme.text}`}&gt;
              &lt;Globe size={16} /&gt; Global Translation: {quadrant.perspective.title}
            &lt;/h4&gt;
            &lt;div className=&quot;flex gap-4 items-start&quot;&gt;
               &lt;div className=&quot;flex-1&quot;&gt;
                 &lt;div className={`text-[10px] font-bold uppercase mb-1 opacity-70 ${quadrant.theme.text}`}&gt;{quadrant.perspective.role}&lt;/div&gt;
                 &lt;p className={`text-sm leading-relaxed italic ${quadrant.theme.text} opacity-90`}&gt;
                   &quot;{quadrant.perspective.text}&quot;
                 &lt;/p&gt;
               &lt;/div&gt;
               &lt;div className=&quot;hidden md:block w-px bg-current opacity-20 self-stretch mx-2&quot;&gt;&lt;/div&gt;
               &lt;div className={`flex-1 text-xs leading-relaxed ${quadrant.theme.text} opacity-80`}&gt;
                 &lt;strong className=&quot;block mb-1 font-bold opacity-100&quot;&gt;Why the tree looks like this:&lt;/strong&gt;
                 {activeQuadId === &#39;P_REP&#39; &amp;&amp; &quot;Every branch splits fully. No restrictions applied.&quot;}
